{
  "conversations": [
    {
      "title": "Rent a surfboard",
      "lines": [
        { "speaker": "you", "text": "Do you rent surfboards?" },
        { "speaker": "partner", "text": "Yes, what size do you need?" },
        { "speaker": "you", "text": "I need a seven-foot funboard, please." },
        { "speaker": "you", "text": "I need an eight-foot longboard, please.", "or": true },
        { "speaker": "partner", "text": "For how many days?" },
        { "speaker": "you", "text": "Just for today." },
        { "speaker": "you", "text": "For three days, please.", "or": true },
        { "speaker": "partner", "text": "That'll be twenty dollars per day." },
        { "speaker": "you", "text": "Here's my passport." }
      ]
    },
    {
      "title": "Ask about wave conditions",
      "lines": [
        { "speaker": "you", "text": "How are the waves today?" },
        { "speaker": "partner", "text": "They're pretty small this morning." },
        { "speaker": "partner", "text": "They're getting big and heavy.", "or": true },
        { "speaker": "you", "text": "Is it good for intermediates?" },
        { "speaker": "partner", "text": "Yes, it's great right now." },
        { "speaker": "partner", "text": "No, it's too dangerous right now.", "or": true },
        { "speaker": "you", "text": "Which beach has better waves?" },
        { "speaker": "partner", "text": "Try the point break down the road." },
        { "speaker": "you", "text": "Thanks for the tip." }
      ]
    },
    {
      "title": "Get local food recommendations",
      "lines": [
        { "speaker": "you", "text": "Where's a good place to eat nearby?" },
        { "speaker": "partner", "text": "Do you want local food or burgers?" },
        { "speaker": "you", "text": "I want traditional Costa Rican food." },
        { "speaker": "you", "text": "I'm looking for cheap seafood.", "or": true },
        { "speaker": "partner", "text": "Go to the soda on the main corner." },
        { "speaker": "you", "text": "What do you recommend there?" },
        { "speaker": "partner", "text": "The fish casado is the best." },
        { "speaker": "you", "text": "Thanks, I'll check it out." }
      ]
    }
  ]
}
